{
  "findings": [
    {
      "ref": "[D517]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child.",
      "stance": "risk",
      "quote": "Kids can set their own passcode to keep siblings out of their profile, but parents can override it or create it themselves."
    },
    {
      "ref": "[D517]",
      "area": "money",
      "claim": "A parent reports that the app pushes in-app purchases and branded content that may be mistaken for ads.",
      "stance": "risk",
      "quote": "Some videos contain kid-focused ads (e.g., for TV shows and websites like Mother Goose Club and Discover the Forest. Some look more like contests and entertainment than ads, making it hard for kids to know they're being marketed to. Videos featuring branded content aren't marked as advertising, are mixed in with other videos. Parents have reported seeing occasional ads with inappropriate content. Some videos are focused on products (e.g., backpacks, toy sets), often titled and filed under \"Unbox It\" (e.g., a video on the Brick Queen channel features unboxing of a Pokémon toy). Other branded content includes videos featuring Disney dolls, Hasbro products, and whole channels from brands such as McDonald's (with videos about Happy Meal toys)."
    },
    {
      "ref": "[D517]",
      "area": "data",
      "claim": "A parent reports that the app collects personal data and shares it with third parties for advertising.",
      "stance": "risk",
      "quote": "Read the developer's privacy policy for details on how your (or your kids') information is collected, used, and shared and any choices you may have in the matter, and note that privacy policies and terms of service frequently change."
    },
    {
      "ref": "[D517]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works in practice by allowing parents to select age-appropriate categories.",
      "stance": "mitigation",
      "quote": "Also, parents can create their own passcodes. In addition to direct, kid-targeted ads, the app has whole channels dedicated to products such as Hasbro toys, Lego, and even McDonald's, as well as lots of videos in which kids can watch someone \"unbox\" a wide variety of toys. Some videos have mild cartoon violence, potentially creepy images, and somewhat suggestive content (e.g., crotch-grabbing during a Michael Jackson dance tutorial). Parents may want to talk with their kids about the product- and brand-centered channels before letting kids find them on their own, and monitor kids' viewing in case adult content sneaks through. Read the developer's privacy policy for details on how your (or your kids') information is collected, used, and shared and any choices you may have in the matter, and note that privacy policies and terms of service frequently change."
    },
    {
      "ref": "[D517]",
      "area": "content",
      "claim": "A parent reports that the app contains mild cartoon violence, potentially creepy images, and suggestive content such as crotch-grabbing.",
      "stance": "risk",
      "quote": "There's mild cartoon violence in some clips. There's some potentially creepy images for younger viewers, as in \"Figaro Pho,\" which features a character who faces phobias and is drawn in a Tim Burton style. Curated content is updated periodically, so degrees of violence and scariness may fluctuate. Also, sometimes scary images are embedded in what at first seem to be kid-friendly videos. Curated videos are updated periodically. Presence of potentially inappropriate content may fluctuate; parents have reported videos containing racy and explicit images (from crotch grabbing during a Michael Jackson dance tutorial to nudity)."
    },
    {
      "ref": "[D517]",
      "area": "developer_record",
      "claim": "A parent reports that the developer has faced regulatory scrutiny and fines for data collection issues.",
      "stance": "risk",
      "quote": "Read the developer's privacy policy for details on how your (or your kids') information is collected, used, and shared and any choices you may have in the matter, and note that privacy policies and terms of service frequently change."
    }
  ]
}
